function readSetting(name) {
  try {
    if (typeof $env !== "undefined" && $env && $env[name]) return String($env[name]);
  } catch (error) {
    // n8n Cloud blocks $env inside nodes; fall through to Global Variables.
  }
  try {
    if (typeof $vars !== "undefined" && $vars && $vars[name]) return String($vars[name]);
  } catch (error) {
    // Self-hosted Community has no Global Variables; fall through.
  }
  return "";
}

function requireSetting(name) {
  const value = readSetting(name);
  if (!value) {
    throw new Error(
      name + " is not configured. Set it as an n8n environment variable ($env) or a Global Variable ($vars).",
    );
  }
  return value;
}

function sign(timestamp, body) {
  const secret = requireSetting("N8N_HMAC_SECRET");
  return require("crypto")
    .createHmac("sha256", secret)
    .update(timestamp + "." + body, "utf8")
    .digest("hex");
}

function convexBaseUrl() {
  return requireSetting("LENDLOOP_CONVEX_SITE_URL").replace(/\/+$/, "");
}

function escapeHtml(value) {
  return String(value === null || value === undefined ? "" : value).replace(
    /[&<>"']/g,
    (character) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character],
  );
}

const event = $input.first().json || {};
const workflow = event.workflow || {};
const execution = event.execution || {};
const error = execution.error || {};

const workflowName = workflow.name || "an unknown workflow";
const nodeName = execution.lastNodeExecuted || "an unknown node";
const message = error.message || event.error || "No error message was provided.";
const executionId = execution.id || "";
const executionUrl = execution.url || "";

const subject = "LendLoop alert: " + workflowName + " failed";
const text = [
  workflowName + " failed.",
  "",
  "Node: " + nodeName,
  "Error: " + message,
  executionId ? "Execution: " + executionId : "",
  executionUrl ? "Open: " + executionUrl : "",
  "",
  "Nothing was retried automatically. Fix the cause, then replay the execution.",
].filter(Boolean).join("\n");

const html = [
  "<p><strong>" + escapeHtml(workflowName) + "</strong> failed.</p>",
  "<p>Node: " + escapeHtml(nodeName) + "<br>Error: " + escapeHtml(message) + "</p>",
  executionUrl
    ? '<p><a href="' + escapeHtml(executionUrl) + '">Open the failed execution</a></p>'
    : "",
  "<p>Nothing was retried automatically. Fix the cause, then replay the execution.</p>",
].join("");

return [
  {
    json: {
      workflowId: workflow.id || "",
      workflowName,
      nodeName,
      message,
      executionId,
      executionUrl,
      from: readSetting("LENDLOOP_FROM_EMAIL") || "LendLoop <notifications@example.com>",
      to: readSetting("LENDLOOP_ALERT_EMAIL"),
      subject,
      text,
      html,
    },
  },
];
